ALTER TABLE h5_hangup_map
    ADD COLUMN sub_region VARCHAR(32) NULL AFTER region_name,
    ADD COLUMN sub_region_name VARCHAR(32) NULL AFTER sub_region,
    ADD COLUMN sub_region_order INT NOT NULL DEFAULT 0 AFTER sub_region_name;

